                prev_sum += nums[i - k] - mid
                min_prev = min(min_prev, prev_sum)
                if curr_sum - min_prev >= 0:
                    return True
            return False

        while right - left > 1e-5:
            mid = (left + right) / 2
            if check(mid):
                left = mid
            else:
                right = mid
        return left
