class Solution {
public:
    double findMaxAverage(vector<int>& nums, int k) {
        double left = nums[0], right = nums[0];
        for (int x : nums) {
            if (x < left) left = x;
            if (x > right) right = x;
        }

        auto check = [&](double mid) {
            double curr = 0;
            for (int i = 0; i < k; i++) curr += nums[i] - mid;
            if (curr >= 0) return true;
            double prev = 0, min_prev = 0;
            for (int i = k; i < (int)nums.size(); i++) {
                curr += nums[i] - mid;
                prev += nums[i - k] - mid;
                min_prev = min(min_prev, prev);
                if (curr - min_prev >= 0) return true;
            }
            return false;
        };

        while (right - left > 1e-5) {
            double mid = (left + right) / 2;
            if (check(mid)) left = mid;
            else right = mid;
        }
        return left;
    }
};

class Solution {
    public double findMaxAverage(int[] nums, int k) {
        double left = nums[0], right = nums[0];
        for (int x : nums) {
            if (x < left) left = x;
            if (x > right) right = x;
        }

        while (right - left > 1e-5) {
            double mid = (left + right) / 2;
            if (check(nums, k, mid)) {
                left = mid;
            } else {
                right = mid;
            }
        }
        return left;
    }

    private boolean check(int[] nums, int k, double mid) {
        double curr = 0;
        for (int i = 0; i < k; i++) curr += nums[i] - mid;
        if (curr >= 0) return true;
        double prev = 0, minPrev = 0;
        for (int i = k; i < nums.length; i++) {
            curr += nums[i] - mid;
            prev += nums[i - k] - mid;
            minPrev = Math.min(minPrev, prev);
            if (curr - minPrev >= 0) return true;
        }
        return false;
    }
}

